#[derive(Copy, Clone, PartialEq, Eq)]
#[repr(u32)]
pub enum PlicPeripheral {
    /// Unknown Peripheral
    Unknown = 0,
    /// pwrmgr
    Pwrmgr = 1,
    /// alert_handler
    AlertHandler = 2,
    /// rv_timer_aon
    RvTimerAon = 3,
    /// otp_ctrl
    OtpCtrl = 4,
    /// rv_timer
    RvTimer = 5,
    /// hmac
    Hmac = 6,
    /// kmac
    Kmac = 7,
    /// otbn
    Otbn = 8,
    /// keymgr_dpe
    KeymgrDpe = 9,
    /// csrng
    Csrng = 10,
    /// entropy_src
    EntropySrc = 11,
    /// edn0
    Edn0 = 12,
    /// edn1
    Edn1 = 13,
    /// dma
    Dma = 14,
    /// mbx0
    Mbx0 = 15,
    /// mbx1
    Mbx1 = 16,
}

impl TryFrom<u32> for PlicPeripheral {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Pwrmgr),
            2 => Ok(Self::AlertHandler),
            3 => Ok(Self::RvTimerAon),
            4 => Ok(Self::OtpCtrl),
            5 => Ok(Self::RvTimer),
            6 => Ok(Self::Hmac),
            7 => Ok(Self::Kmac),
            8 => Ok(Self::Otbn),
            9 => Ok(Self::KeymgrDpe),
            10 => Ok(Self::Csrng),
            11 => Ok(Self::EntropySrc),
            12 => Ok(Self::Edn0),
            13 => Ok(Self::Edn1),
            14 => Ok(Self::Dma),
            15 => Ok(Self::Mbx0),
            16 => Ok(Self::Mbx1),
            _ => Err(val),
        }
    }
}

